// QR 编码器单测:三条腿验证。
// (A) 独立 oracle 对拍(fixture 由 segno 1.6.6 在 230 仓库外临时 venv /tmp/qrvenv 生成):
//     A1 功能图案+格式信息与 segno 矩阵逐模块一致(几何 + BCH(15,5) + BCH(18,6));
//     A2 我的矩阵解出的码字全流 == segno 内部 make_final_message(RS+交织)对标准码流
//        的输出 —— RS(GF(256),0x11D)、块拆分、交织、掩码公式、byte 编码全部对拍;
//     A3 segno 自身矩阵解出的码字与期望在载荷前缀 [0, payloadCodewords) 完全一致,
//        差异只出现在填充区之后 —— 原因:segno 1.6.6 的 write_padding_bits 用
//        8-(len%8) 而非 (8-len%8)%8,当码流已对齐字节边界时仍多补一个完整 0x00
//        字节(偏离 ISO 18004 7.4.10);本实现按标准处理,故矩阵级逐位对拍对
//        byte 模式不可行,改用 A1/A2/A3 三层等价对拍。
//     segno.make 调用钉死:error='m', 显式 version+mask, mode='byte',
//     encoding='utf-8', boost_error=False;版本与本实现自动选版一致。
// (B) 自解码回读:测试内实现极简解码器(读格式信息→去掩码→zigzag 读码字→
//     去交织→RS syndrome 校验→解析 byte 模式),断言原样还原(含中文 UTF-8 往返)。
//     (A) 是对外部真对拍,(B) 是内部一致性;两者互补防"共享错误假设"。
// (C) 边界:空串 / 容量边界 / 超容量抛错 / mask 0-7 与格式信息一致性 / qrToSvg。
import { describe, it, expect } from "vitest";
import { encodeQrMatrix, qrToSvg } from "../../src/utils/qrcode.js";

interface FixtureCase {
  content: string;
  version: number;
  mask: number;
  matrix: string[];
  /** segno 内部 make_final_message 对标准码流(RS+交织)的期望码字(十六进制) */
  expectedCodewords: string[];
  /** segno make_blocks 的块数据展平(去交织域的期望数据码字,十六进制) */
  expectedDataCodewords: string[];
  /** 载荷(模式+长度+数据+终止符)占用的码字数,填充区从此之后开始 */
  payloadCodewords: number;
}

