function gfMul(a: number, b: number): number {
  let z = 0;
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d);
    z ^= ((b >>> i) & 1) * a;
  }
  return z & 0xff;
}

/** 读取第一份格式信息并做 BCH(15,5) 校验,解出 ECC 与 mask */
function readFormatBits(matrix: boolean[][]): { ecc: string; mask: number } {
  const cells: Array<[number, number]> = [];
  for (let i = 0; i <= 5; i++) cells.push([8, i]);
  cells.push([8, 7], [8, 8], [7, 8]);
  for (let i = 9; i < 15; i++) cells.push([14 - i, 8]);
  let bits = 0;
  cells.forEach(([x, y], i) => {
    if (matrix[y][x]) bits |= 1 << i;
  });
  const decoded = (bits ^ 0x5412) & 0x7fff;
  const data = decoded >>> 10;
  const rem = decoded & 0x3ff;
  let r = data;
  for (let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
  expect(r).toBe(rem); // BCH 校验:重算余数必须一致
  const ecc = ECC_FROM_FORMAT[data >>> 3];
  expect(ecc).toBeDefined();
  return { ecc: ecc as string, mask: data & 7 };
}

function maskBit(mask: number, row: number, col: number): boolean {
  switch (mask) {
    case 0:
      return (row + col) % 2 === 0;
    case 1:
      return row % 2 === 0;
    case 2:
      return col % 3 === 0;
    case 3:
      return (row + col) % 3 === 0;
    case 4:
      return (Math.floor(row / 2) + Math.floor(col / 3)) % 2 === 0;
    case 5:
      return ((row * col) % 2) + ((row * col) % 3) === 0;
    case 6:
      return (((row * col) % 2) + ((row * col) % 3)) % 2 === 0;
    case 7:
      return (((row * col) % 3) + ((row + col) % 2)) % 2 === 0;
    default:
      throw new Error(`bad mask ${mask}`);
  }
}

/** 独立重算功能模块集合(定位图案+分隔符+时序+校正+暗模块+格式+版本信息区) */
function functionCells(version: number): boolean[][] {
  const size = version * 4 + 17;
  const isFn: boolean[][] = Array.from({ length: size }, () => new Array<boolean>(size).fill(false));
  const mark = (x: number, y: number): void => {
    isFn[y][x] = true;
  };
  for (const [cx, cy] of [
    [3, 3],
    [size - 4, 3],
    [3, size - 4],
  ]) {
    for (let dy = -4; dy <= 4; dy++) {
      for (let dx = -4; dx <= 4; dx++) {
        const x = cx + dx;
        const y = cy + dy;
        if (x >= 0 && x < size && y >= 0 && y < size) mark(x, y);
      }
    }
  }
  for (let i = 8; i < size - 8; i++) {
    mark(i, 6);
    mark(6, i);
  }
  const last = size - 7;
  for (const cy of ALIGN_POS[version - 1]) {
    for (const cx of ALIGN_POS[version - 1]) {
      if ((cx === 6 && cy === 6) || (cx === 6 && cy === last) || (cx === last && cy === 6)) continue;
      for (let dy = -2; dy <= 2; dy++) {
        for (let dx = -2; dx <= 2; dx++) mark(cx + dx, cy + dy);
      }
    }
  }
  mark(8, size - 8); // 暗模块
  for (let i = 0; i <= 5; i++) mark(8, i);
  mark(8, 7);
  mark(8, 8);
  mark(7, 8);
  for (let i = 9; i < 15; i++) mark(14 - i, 8);
  for (let i = 0; i < 8; i++) mark(size - 1 - i, 8);
  for (let i = 8; i < 15; i++) mark(8, size - 15 + i);
  if (version >= 7) {
    for (let i = 0; i < 18; i++) {
      const a = size - 11 + (i % 3);
      const b = Math.floor(i / 3);
      mark(a, b);
      mark(b, a);
    }
  }
  return isFn;
}

interface Analysis {
  version: number;
  ecc: string;
  mask: number;
  isFn: boolean[][];
  /** 去掩码并按 zigzag 读出的完整码字序列(数据+填充+ECC,未做交织还原) */
  codewords: number[];
}

/** 解析矩阵:格式信息 → 去掩码 → zigzag 读码字(不含 RS 校验与去交织) */
function analyzeQr(matrix: boolean[][]): Analysis {
  const size = matrix.length;
  const version = (size - 17) / 4;
  expect(version).toBeGreaterThanOrEqual(1);
  expect(version).toBeLessThanOrEqual(10);
  const isFn = functionCells(version);
  const { ecc, mask } = readFormatBits(matrix);

  const unmasked = matrix.map((row) => row.slice());
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      if (!isFn[y][x] && maskBit(mask, y, x)) unmasked[y][x] = !unmasked[y][x];
    }
  }

  const bits: number[] = [];
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let vert = 0; vert < size; vert++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j;
        const upward = ((right + 1) & 2) === 0;
        const y = upward ? size - 1 - vert : vert;
        if (!isFn[y][x]) bits.push(unmasked[y][x] ? 1 : 0);
      }
    }
  }
  const codewords: number[] = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    let b = 0;
    for (let j = 0; j < 8; j++) b = (b << 1) | bits[i + j];
    codewords.push(b);
  }
  return { version, ecc, mask, isFn, codewords };
}

/** 去交织(逆交织):返回各块内容与拼接后的数据码字序列 */
function deinterleave(codewords: number[], ecc: string, version: number): {
  blocks: number[][];
  blockEccLen: number;
  numShortBlocks: number;
  data: number[];
} {
  const numBlocks = NUM_BLOCKS[ecc][version - 1];
  const blockEccLen = ECC_PER_BLOCK[ecc][version - 1];
  const numShortBlocks = numBlocks - (codewords.length % numBlocks);
  const shortBlockLen = Math.floor(codewords.length / numBlocks);
  const blocks: number[][] = Array.from({ length: numBlocks }, () =>
    new Array<number>(shortBlockLen + 1).fill(0)
  );
  let p = 0;
  for (let i = 0; i < shortBlockLen + 1; i++) {
    for (let j = 0; j < numBlocks; j++) {
      if (i === shortBlockLen - blockEccLen && j < numShortBlocks) continue;
      blocks[j][i] = codewords[p++];
    }
  }
  expect(p).toBe(codewords.length);
  const data: number[] = [];
  for (let j = 0; j < numBlocks; j++) {
    const dLen = shortBlockLen - blockEccLen + (j < numShortBlocks ? 0 : 1);
    data.push(...blocks[j].slice(0, dLen));
  }
  return { blocks, blockEccLen, numShortBlocks, data };
}

/** 输入必须是无 border 的方阵;去交织 + RS syndrome 校验 + 解析 byte 模式 */
function decodeQr(matrix: boolean[][]): string {
  const { version, ecc, codewords } = analyzeQr(matrix);
  const { blocks, blockEccLen, numShortBlocks, data: dataCws } = deinterleave(
    codewords,
    ecc,
    version
  );

  // RS syndrome 校验(生成多项式根为 alpha^0..alpha^(n-1),无错时全零)
  const alphaPow: number[] = [1];
  for (let i = 1; i <= blockEccLen; i++) alphaPow.push(gfMul(alphaPow[i - 1], 2));
  for (let j = 0; j < blocks.length; j++) {
    const dLen = blocks[j].length - blockEccLen - (j < numShortBlocks ? 1 : 0);
    const dataPart = blocks[j].slice(0, dLen);
    const eccPart = blocks[j].slice(j < numShortBlocks ? dLen + 1 : dLen);
    expect(eccPart.length).toBe(blockEccLen);
    const msg = dataPart.concat(eccPart);
    for (let s = 0; s < blockEccLen; s++) {
      let acc = 0;
      for (const b of msg) acc = gfMul(acc, alphaPow[s]) ^ b;
      expect(acc).toBe(0);
    }
  }

  // 解析 byte 模式
  let bp = 0;
  const readBits = (n: number): number => {
    let v = 0;
    for (let i = 0; i < n; i++) {
      v = (v << 1) | ((dataCws[bp >> 3] >>> (7 - (bp & 7))) & 1);
      bp++;
    }
    return v;
  };
  expect(readBits(4)).toBe(0b0100); // byte 模式指示符
  const len = readBits(version <= 9 ? 8 : 16);
  expect(len).toBeLessThanOrEqual(dataCws.length);
  const out: number[] = [];
  for (let i = 0; i < len; i++) out.push(readBits(8));
  return Buffer.from(out).toString("utf8");
}

// ---------------------------------------------------------------------------
// (A) segno oracle 对拍(三层)
// ---------------------------------------------------------------------------

describe("(A) segno oracle 对拍", () => {
  for (const f of FIXTURES) {
    const opts = { ecc: "M" as const, version: f.version, mask: f.mask, border: 0 };

    it(`A1 功能图案+格式信息逐模块一致 v${f.version} mask${f.mask}「${shortLabel(f.content)}」`, () => {
      const got = encodeQrMatrix(f.content, opts);
      const want = toMatrix(f.matrix);
      const isFn = functionCells(f.version);
      const diffs: string[] = [];
      for (let y = 0; y < want.length; y++) {
        for (let x = 0; x < want.length; x++) {
          if (isFn[y][x] && got[y][x] !== want[y][x]) diffs.push(`${x},${y}`);
        }
      }
      expect(diffs).toEqual([]);
    });

    it(`A2 码字全流 == segno RS+交织(标准码流) v${f.version} mask${f.mask}`, () => {
      const got = encodeQrMatrix(f.content, opts);
      const { codewords } = analyzeQr(got);
      expect(codewords.map((c) => c.toString(16).padStart(2, "0"))).toEqual(f.expectedCodewords);
    });

    it(`A3 segno 矩阵去交织域载荷前缀一致,差异仅填充后缀 v${f.version} mask${f.mask}`, () => {
      const mine = analyzeQr(encodeQrMatrix(f.content, opts));
      const theirs = analyzeQr(toMatrix(f.matrix));
      // 多块版本交织流中填充码字按列混入流中部,故在去交织域(块顺序)比较
      const mineData = deinterleave(mine.codewords, mine.ecc, f.version).data.map(hex);
      const theirsData = deinterleave(theirs.codewords, theirs.ecc, f.version).data.map(hex);
      expect(theirsData.length).toBe(mineData.length);
      const k = f.payloadCodewords;
      expect(theirsData.slice(0, k)).toEqual(f.expectedDataCodewords.slice(0, k));
      const firstDiff = theirsData.findIndex((c, i) => c !== mineData[i]);
      expect(firstDiff).toBeGreaterThanOrEqual(k); // 差异不得侵入载荷区
    });
  }
});

// ---------------------------------------------------------------------------
// (B) 自解码回读
// ---------------------------------------------------------------------------

describe("(B) 自解码回读", () => {
  for (const f of FIXTURES) {
    it(`还原 v${f.version} mask${f.mask}「${shortLabel(f.content)}」`, () => {
      const m = encodeQrMatrix(f.content, {
        ecc: "M",
        version: f.version,
        mask: f.mask,
        border: 0,
      });
      expect(decodeQr(m)).toBe(f.content);
    });
  }

  it("自动选掩码同样可自解码(含中文 UTF-8 往返)", () => {
    for (const s of ["HELLO WORLD", LOGIN_URL, "abcdefgh", "x".repeat(200), "你好，世界"]) {
      expect(decodeQr(encodeQrMatrix(s, { border: 0 }))).toBe(s);
    }
  });

  it("默认参数(border=4)矩阵剥离边框后可自解码", () => {
    const m = encodeQrMatrix("你好，世界");
    const inner = m.slice(4, m.length - 4).map((r) => r.slice(4, r.length - 4));
    expect(decodeQr(inner)).toBe("你好，世界");
  });
});

// ---------------------------------------------------------------------------
// (C) 边界用例
// ---------------------------------------------------------------------------

describe("(C) 边界用例", () => {
  it("空串可编码(v1-M)且可自解码", () => {
    const m = encodeQrMatrix("", { border: 0 });
    expect(m.length).toBe(21);
    expect(decodeQr(m)).toBe("");
  });

  it("容量边界:14 字节是 v1-M 上限,15 字节自动升 v2", () => {
    expect(encodeQrMatrix("x".repeat(14)).length).toBe(21 + 8);
    expect(encodeQrMatrix("x".repeat(15)).length).toBe(25 + 8);
  });

  it("显式版本恰好装满(v1-M 14 字节)", () => {
    expect(() => encodeQrMatrix("x".repeat(14), { version: 1, mask: 0 })).not.toThrow();
  });

  it("超容量必须抛错(显式版本 / 自动版本均不静默截断)", () => {
    expect(() => encodeQrMatrix("x".repeat(15), { version: 1 })).toThrow(/容量/);
    expect(() => encodeQrMatrix("x".repeat(500))).toThrow(/容量/);
    expect(() => encodeQrMatrix("x".repeat(500), { version: 10, ecc: "H" })).toThrow(/容量/);
  });

  it("mask 0-7 全部可用,格式信息随之改变,产出 8 个不同矩阵", () => {
    const seen = new Set<string>();
    for (let mask = 0; mask < 8; mask++) {
      const m = encodeQrMatrix("HELLO WORLD", { mask, border: 0 });
      expect(readFormatBits(m).mask).toBe(mask);
      seen.add(toStrs(m).join("|"));
    }
    expect(seen.size).toBe(8);
  });

  it("非法参数抛错", () => {
    expect(() => encodeQrMatrix("hi", { mask: 8 })).toThrow(/掩码/);
    expect(() => encodeQrMatrix("hi", { mask: -1 })).toThrow(/掩码/);
    expect(() => encodeQrMatrix("hi", { version: 0 })).toThrow(/版本/);
    expect(() => encodeQrMatrix("hi", { version: 11 })).toThrow(/版本/);
    expect(() => encodeQrMatrix("hi", { ecc: "X" as never })).toThrow(/ECC/);
  });
});

// ---------------------------------------------------------------------------
// qrToSvg
// ---------------------------------------------------------------------------

describe("qrToSvg", () => {
  it("自包含 SVG:含 xmlns、无脚本、无外部引用,尺寸 = 模块数*moduleSize", () => {
    const svg = qrToSvg("hi");
    expect(svg).toContain('xmlns="http://www.w3.org/2000/svg"');
    expect(svg).not.toContain("<script");
    expect(svg).not.toContain("href");
    expect(svg).toContain(`width="${encodeQrMatrix("hi").length * 8}"`);
  });

  it("自定义 dark/light/moduleSize 生效,特殊字符做 XML 转义", () => {
    const svg = qrToSvg("hi", { moduleSize: 3, dark: "#123456", light: "#abcdef" });
    expect(svg).toContain('fill="#123456"');
    expect(svg).toContain('fill="#abcdef"');
    expect(svg).toContain(`width="${encodeQrMatrix("hi").length * 3}"`);
    const esc = qrToSvg("hi", { light: 'a&b<c>"d' });
    expect(esc).toContain("&amp;");
    expect(esc).not.toContain('fill="a&b');
  });
});
